<?php
require_once __DIR__.'/config/db.php';
require_once __DIR__ . '/includes/image_upload.php';
$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM catalogs WHERE id=?");$s->execute([$id]);$catalog=$s->fetch();if(!$catalog)exit('Catálogo no encontrado');
$s=$pdo->prepare("SELECT p.*,cat.name category_name FROM products p LEFT JOIN categories cat ON cat.id=p.category_id WHERE p.catalog_id=? ORDER BY p.name");$s->execute([$id]);$products=$s->fetchAll();
$html='<html><head><meta charset="UTF-8"><style>
@page{margin:32px 35px}body{font-family:DejaVu Sans,sans-serif;color:#25233a;font-size:11px}.cover{background:#292443;color:white;padding:28px;border-radius:12px;margin-bottom:22px}.brand{color:#b9a9ff;font-size:10px;letter-spacing:3px}.cover h1{font-size:27px;margin:14px 0 8px}.cover p{color:#e2def4;line-height:1.6}.meta{color:#777;font-size:10px;margin-bottom:18px}.grid{width:100%;border-collapse:separate;border-spacing:8px}.item{border:1px solid #e7e5ef;border-radius:9px;padding:12px;vertical-align:top;width:50%}.product-photo{display:block;max-width:100%;height:115px;object-fit:contain;margin:0 auto 8px}.product-photo-placeholder{height:115px;margin:0 0 8px;background:#f3f2f8;color:#888;display:flex;align-items:center;justify-content:center}.tag{color:#7964d8;font-size:9px;text-transform:uppercase}.name{font-size:14px;font-weight:bold;margin:8px 0}.desc{color:#666;line-height:1.5;min-height:30px}.price{font-size:14px;color:#4b3d9b;font-weight:bold;margin-top:10px}.foot{border-top:1px solid #eee;padding-top:10px;color:#888;font-size:9px}
</style></head><body><div class="cover"><div class="brand">CATALOG STUDIO</div><h1>'.h($catalog['name']).'</h1><p>'.nl2br(h($catalog['description'])).'</p></div><div class="meta">'.h($catalog['category']?:'Catálogo general').' &nbsp; • &nbsp; '.count($products).' productos &nbsp; • &nbsp; '.date('d/m/Y').'</div><table class="grid">';
foreach(array_chunk($products,2) as $pair){$html.='<tr>';foreach($pair as $p){$html.='<td class="item">';$photo=product_image_data_uri($p['image']);if($photo!==null){$html.='<img class="product-photo" src="'.h($photo).'" alt="">';}else{$html.='<div class="product-photo-placeholder">Sin fotografía</div>';}$html.='<div class="tag">'.h($p['category_name']?:'Producto').'</div><div class="name">'.h($p['name']).'</div><div class="desc">'.nl2br(h($p['description'])).'</div><div class="price">$'.number_format((float)$p['price'],0,',','.').' COP</div></td>'; }if(count($pair)===1)$html.='<td></td>';$html.='</tr>';}$html.='</table><div class="foot">Catálogo generado con Catalog Studio</div></body></html>';
if(file_exists(__DIR__.'/vendor/autoload.php')){require __DIR__.'/vendor/autoload.php';$dompdf=new Dompdf\Dompdf(['isRemoteEnabled'=>false]);$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4','portrait');$dompdf->render();$dompdf->stream(preg_replace('/[^a-zA-Z0-9_-]/','_', $catalog['name']).'.pdf',['Attachment'=>true]);exit;}
?><!doctype html><html lang="es"><meta charset="utf-8"><title>Vista para PDF</title><body><?= preg_replace('/<\\/?html>|<head>.*?<\\/head>|<body>|<\\/body>/s','',$html) ?><script>window.onload=()=>window.print()</script></body></html>
